for lang,tree in extra.items():
 p=root/f'{lang}.json';d=json.loads(p.read_text())
 def merge(a,b):
  for k,v in b.items():
   if isinstance(v,dict):
    a.setdefault(k,{})
    merge(a[k],v)
   else:a[k]=v
 merge(d,tree);p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');print(lang,'merged')
